package com.tuap.backend.auth;
import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import org.springframework.stereotype.Component; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.tuap.backend.config.EmailProperties;
@Component @ConditionalOnProperty(prefix="app.email",name="enabled",havingValue="true") public class EmailChangeNotifier { private final EmailService email; private final EmailProperties properties; public EmailChangeNotifier(EmailService e,EmailProperties p){email=e;properties=p;} public void notifyChange(String target,String token){String url=properties.getEmailChangeConfirmUrl()+"?token="+URLEncoder.encode(token,StandardCharsets.UTF_8);email.send(target,"Confirma tu nuevo correo de NextFit","<p>Has solicitado cambiar tu correo de NextFit.</p><p><a href=\""+url+"\">Confirmar nuevo correo</a></p><p>Este enlace caduca en 30 minutos. Si no lo solicitaste, ignora este mensaje.</p>");}}
